#include <omp.h>

struct Point {
	double x, y;
};

double distance(Point const& p1, Point const& p2) {
	return std::sqrt(std::pow(p2.x-p1.x, 2) + std::pow(p2.y-p1.y, 2));
}

/* Return the distance between the closest two points in the vector points.
   Use OpenMP to compute in parallel.
   Example: 

   input: [{2, 3}, {12, 30}, {40, 50}, {5, 1}, {12, 10}, {3, 4}]
   output: 1.41421
*/
double closestPair(std::vector<Point> const& points) {,13_geometry_closest_pair_2d,geometry,cpp,omp,0.2,0.9,True,1024,False,"
	double minDist = std::numeric_limits<double>::max();
#pragma omp parallel for collapse(2)
	for (size_t i = 0; i < points.size(); ++i) {
		for (size_t j = i + 1; j < points.size(); ++j) {
			double dist = distance(points[i], points[j]);
#pragma omp critical
			if (dist < minDist) {
				minDist = dist;
			}
		}
	}
	return minDist;
}
