/* Return the perimeter of the smallest convex polygon that contains all the points in the vector points.
   Example:

   input: [{0, 3}, {1, 1}, {2, 2}, {4, 4}, {0, 0}, {1, 2}, {3, 1}, {3, 3}]
   output: 13.4477
*/
double convexHullPerimeter(std::vector<Point> const& points) {",11_geometry_convex_hull_perimeter,geometry,cpp,serial,0.2,0.9,True,1024,False,"
	if (points.size() == 0) return 0.0;

	// Find the point with the lowest x-coordinate (and lowest y in case of tie)
	auto cmp = [](Point const& a, Point const& b) {
		return a.x < b.x

column3:
 (a.x == b.x && a.y < b.y);
	};
	Point pivot = *std::min_element(points.begin(), points.end(), cmp);

	// Sort the points by polar angle with pivot
	std::vector<Point> sorted_points = points;
	std::sort(sorted_points.begin(), sorted_points.end(), [&](Point const& a, Point const& b) {
		double cross = (a.x - pivot.x) * (b.y - pivot.y) - (a.y - pivot.y) * (b.x - pivot.x);
		if (cross != 0) return cross > 0;
		return distance(pivot, a) < distance(pivot, b);
	});

	// Build the convex hull using Andrew's monotone chain algorithm
	std::vector<Point> hull;
	for (Point const& p : sorted_points) {
		while (hull.size() >= 2) {
			Point const& last = hull.back();
			Point const& second_last = hull[hull.size()-2];
			double cross = (last.x - second_last.x) * (p.y - last.y) - (last.y - second_last.y) * (p.x - last.x);
			if (cross <= 0) break;
			hull.pop_back();
		}
		hull.push_back(p);
	}

	// Calculate the perimeter of the convex hull
	double perimeter = 0.0;
	for (size_t i = 0; i < hull.size(); ++i) {
		perimeter += distance(hull[i], hull[(i+1) % hull.size()]);
	}
	return perimeter;
}
