struct Point {
	double x, y;
};

double triangleArea(Point const& A, Point const& B, Point const& C) {
  return 0.5 * std::abs( A.x*(B.y-C.y) + B.x*(C.y-A.y) + C.x*(A.y-B.y) );
}

/* Return the area of the smallest triangle that can be formed by any 3 points.
   Use OpenMP to compute in parallel.
   Example:

   input: [{0, 10}, {5, 5}, {1,0}, {-1, 1}, {-10, 0}]
   output: 5.5
*/
double smallestArea(std::vector<Point> const& points) {,12_geometry_smallest_triangle,geometry,cpp,omp,0.2,0.9,True,1024,False,"
	double minArea = std::numeric_limits<double>::infinity();
	int n = points.size();

	#pragma omp parallel
	{
		double localMin = std::numeric_limits<double>::infinity();

		#pragma omp for
		for (int i = 0; i < n; ++i) {
			for (int j = i + 1; j < n; ++j) {
				for (int k = j + 1; k < n; ++k) {
					double area = triangleArea(points[i], points[j], points[k]);
					if (area < localMin) {
						localMin = area;
					}
				}
			}
		}

		#pragma omp critical
		{
			if (localMin < minArea) {
				minArea = localMin;
			}
		}
	}

	return minArea;
}
