    shared_min_area = HUGE_VAL;
  }
  __syncthreads();

  for (size_t i = 0; i < N; ++i) {
    for (size_t j = i + 1; j < N; ++j) {
      for (size_t k = j + 1; k < N; ++k) {
        double area_val = triangleArea(points[i], points[j], points[k]);
        if (area_val < shared_min_area) {
