/* Solve the linear system Ax=b for x.
   A is an NxN matrix in row-major. x and b have N elements.
   Example:

   input: A=[[1,4,2], [1,2,3], [2,1,3]] b=[11, 11, 13]
   output: x=[3, 1, 2]
*/
void solveLinearSystem(std::vector<double> const& A, std::vector<double> const& b, std::vector<double> &x, size_t N) {",01_dense_la_solve,dense_la,cpp,serial,0.2,0.9,True,1024,False,"
    // Create a copy of A and b to avoid modifying the input
    std::vector<std::vector<double>> mat(N, std::vector<double>(N));
    std::vector<double> b_copy = b;

    // Fill the matrix
    for (size_t i = 0; i < N; ++i)
        for (size_t j = 0; j < N; ++j)
            mat[i][j] = A[i * N + j];

    // Forward elimination
    for (size_t i = 0; i < N; ++i) {
        // Find the pivot row
        size_t max_row = i;
        for (size_t k = i + 1; k < N; ++k)
            if (std::abs(mat[k][i]) > std::abs(mat[max_row][i]))
                max_row = k;

        // Swap rows
        std::swap(mat[i], mat[max_row]);
        std::swap(b_copy[i], b_copy[max_row]);

        // Make all rows below this one 0 in current column
        for (size_t k = i + 1; k < N; ++k) {
            double factor = mat[k][i] / mat[i][i];
            for (size_t j = i; j < N; ++j)
                mat[k][j] -= factor * mat[i][j];
            b_copy[k] -= factor * b_copy[i];
        }
    }

    // Back substitution
    x.resize(N);
    for (int i = N - 1; i >= 0; --i) {
        double sum = 0.0;
        for (size_t j = i + 1; j < N; ++j)
            sum += mat[i][j] * x[j];
        x[i] = (b_copy[i] - sum) / mat[i][i];
    }
}
