__global__ void findKthSmallest(const int *x, size_t N, int k, int *kthSmallest) {,41_sort_k-th_smallest_element,sort,cpp,cuda,0.2,0.9,True,1024,False,
    extern __shared__ int shared[];

    unsigned int tid = threadIdx.x;
