__global__ void sortIgnoreZero(int *x, size_t N) {",44_sort_sort_non-zero_elements,sort,cpp,cuda,0.2,0.9,True,1024,False,
int idx = blockIdx.x * blockDim.x + threadIdx.x;
if (idx >= N) return;

__shared__ bool sorted;
if (threadIdx.x == 0) sorted = false;
__syncthreads();

while (!sorted) {
    if (threadIdx.x == 0) sorted = true;
    __syncthreads();

    for (int stride = 1; stride < N; stride *= 2) {
        if (idx % (2 * stride) == 0 && idx + stride < N) {
            int val_i = x[idx];
            int val_j = x[idx + stride];

            if (val_i != 0 && val_j != 0) {
                if (val_i > val_j) {
                    x[idx] = val_j;
                    x[idx + stride] = val_i;
                    if (threadIdx.x == 0) sorted = false;
                }
            }
        }
        __syncthreads();
    }
}
