        Y[i] = 0.0;
    }

    #pragma omp for
    for (size_t a_idx = 0; a_idx < A.size(); ++a_idx) {
        COOElement const& a = A[a_idx];
        size_t a_row = a.row;
        size_t a_col = a.column;
        double a_val = a.value;

        for (size_t x_idx = 0; x_idx < X.size(); ++x_idx) {
