for (const auto& elem : A) {
    A_dense[elem.row][elem.column] = elem.value;
}

L.resize(N * N, 0.0);
U.resize(N * N, 0.0);

#pragma omp parallel for
for (size_t i = 0; i < N; ++i) {
    L[i * N + i] = 1.0;
}

#pragma omp parallel for collapse(2)
for (size_t i = 0; i < N; ++i) {
    for (size_t k = 0; k < N; ++k) {
        U[i * N + k] = A_dense[i][k];
        for (size_t j = 0; j < i; ++j) {
