void luFactorize(std::vector<COOElement> const& A, std::vector<double> &L, std::vector<double> &U, size_t N) {
    std::vector<std::vector<double>> mat(N, std::vector<double>(N, 0.0));
    for (auto const& elem : A) {
        mat[elem.row][elem.column] = elem.value;
    }
    for (size_t i = 0; i < N; ++i) {
        L.push_back(1.0);
        U.push_back(mat[0][0]);
        for (size_t j = 1; j < N; ++j) {
            L.push_back(mat[j][0] / mat[0][0]);
            mat[j][i] -= L.back() * mat[0][i];
        }
        for (size_t j = 1; j < N; ++j) {
            U.push_back(mat[0][j]);
            mat[i][j] -= L[0] * U[j];
        }
        for (size_t k = 1; k < N; ++k) {
            double sum = 0.0;
            for (size_t m = 0; m < k; ++m) {
                sum += L[k * N + m] * U[m * N + k];
            }
            L[k * N + k] = 1.0;
            U[k * N + k] = mat[k][k] - sum;
            for (size_t j = k + 1; j < N; ++j) {
                sum = 0.0;
                for (size_t m = 0; m < k; ++m) {
                    sum += L[j * N + m] * U[m * N + k];
                }
                L[j * N + k] = (mat[j][k] - sum) / U[k * N + k];
            }
            for (size_t j = k + 1; j < N; ++j) {
                sum = 0.0;
                for (size_t m = 0; m < k; ++m) {
                    sum += L[k * N + m] * U[m * N + j];
                }
                U[k * N + j] = mat[k][j] - sum;
            }
        }
    }
}
