                sum += input[(i+1) * N + j];
                count++;
            }

            // Left neighbor
            if (j > 0) {
                sum += input[i * N + (j-1)];
                count++;
            }

            // Right neighbor
            if (j < N-1) {
                sum += input[i * N + (j+1)];
                count++;
            }

