    const size_t N = x.size();
    if (N <= 1) return;

    for (size_t i = 1, j = 0; i < N; ++i) {
        int bit = N >> 1;
        for (; j >= bit; bit >>= 1) j -= bit;
        j += bit;
        if (i < j) std::swap(x[i], x[j]);
    }

    for (size_t n = 2; n <= N; n <<= 1) {
        double theta = -2 * M_PI / n;
        std::complex<double> w_n(std::cos(theta), std::sin(theta));
        for (size_t k = 0; k < N; k += n) {
            std::complex<double> w(1);
            for (size_t m = 0; m < n/2; ++m) {
                std::complex<double> t = w * x[k + m + n/2];
                std::complex<double> u = x[k + m];
                x[k + m] = u + t;
                x[k + m + n/2] = u - t;
                w *= w_n;
            }
        }
    }

    for (auto &val : x) {
        val = std::conj(val);
    }
}
