/* Compute the prefix sum array of the vector x and compute its sum. Store the result in sum.
   Use CUDA to compute in parallel. The kernel is launched with at least as many threads as values in x.
   Example:

   input: [-7, 2, 1, 9, 4, 8]
   output: 15
*/
__global__ void sumOfPrefixSum(const double *x, size_t N, double *sum) {,32_scan_sum_of_prefix_sum_array,scan,cpp,cuda,0.2,0.9,True,1024,False,"
    extern __shared__ double sdata[];

    int tid = threadIdx.x;
    int bid = blockIdx.x;
    int blockSize = blockDim.x;
    int globalThreadId = bid * blockSize + tid;

    // Load data into shared memory
    if (globalThreadId < N) {
        sdata[tid] = x[globalThreadId];
    } else {
        sdata[tid] = 0.0;
    }

    __syncthreads();

    // Build prefix sum in shared memory
    for (int stride = 1; stride < blockSize; stride *= 2) {
        int index = (tid + 1) * stride * 2 - 1;
        if (index < blockSize && (index - stride) >= 0) {
            if ((globalThreadId - stride + 1) >= 0 && globalThreadId < N) {
                sdata[index] += sdata[index - stride];
            }
        }
        __syncthreads();
    }

    // Clear the last element if necessary
    if (tid == 0) {
        sdata[blockSize - 1] = 0;
    }
    __syncthreads();

    // Reverse the build process
    for (int stride = blockSize / 2; stride > 0; stride /= 2) {
        int index = (tid + 1) * stride * 2 - 1;
        if (index < blockSize && (index - stride) >= 0) {
            double temp = sdata[index];
            sdata[index] += sdata[index - stride];
            sdata[index - stride] = temp;
        }
        __syncthreads();
    }

    // Write results to global memory and compute prefix sums
    if (globalThreadId < N) {
        double prefixSum = sdata[tid];
        atomicAdd(sum, prefixSum);
    }
}
